package com.findbyclap.app;

/** Built-in alarm sounds, generated by the app itself so no sound files are needed. */
public final class ToneSynth {
    public static final int RATE = 22050;

    public static final String[] KEYS = {"bird", "cuckoo", "siren", "beeps"};
    public static final String[] NAMES = {"Bird chirping", "Cuckoo", "Siren", "Loud beeps"};

    private ToneSynth() {
    }

    public static boolean isBuiltIn(String key) {
        for (String k : KEYS) {
            if (k.equals(key)) {
                return true;
            }
        }
        return false;
    }

    /** One loop of the sound, ready to repeat. */
    public static short[] make(String key) {
        switch (key) {
            case "bird":
                return bird();
            case "cuckoo":
                return cuckoo();
            case "siren":
                return siren();
            default:
                return beeps();
        }
    }

    private static short[] buffer(double seconds) {
        return new short[(int) (seconds * RATE)];
    }

    /** Adds a note whose pitch glides from f0 to f1, with soft start and end. */
    private static void note(short[] out, double at, double dur, double f0, double f1,
                             double vibratoHz, double vibratoDepth, double amp) {
        int start = (int) (at * RATE);
        int n = (int) (dur * RATE);
        double phase = 0;
        for (int i = 0; i < n && start + i < out.length; i++) {
            double t = (double) i / n;
            double f = f0 + (f1 - f0) * t;
            if (vibratoHz > 0) {
                f += vibratoDepth * Math.sin(2 * Math.PI * vibratoHz * i / RATE);
            }
            phase += 2 * Math.PI * f / RATE;
            double env = Math.min(1, Math.min(t / 0.12, (1 - t) / 0.2));
            double v = out[start + i] + amp * env * 30000 * Math.sin(phase);
            out[start + i] = (short) Math.max(-32767, Math.min(32767, v));
        }
    }

    private static short[] bird() {
        short[] s = buffer(2.2);
        // two rising chirps, a fast trill, then a falling call
        note(s, 0.00, 0.11, 2600, 4400, 0, 0, 1);
        note(s, 0.16, 0.11, 2800, 4700, 0, 0, 1);
        for (int i = 0; i < 7; i++) {
            note(s, 0.36 + i * 0.07, 0.05, 4200, 3300, 0, 0, 1);
        }
        note(s, 0.95, 0.28, 4600, 2900, 28, 350, 1);
        note(s, 1.35, 0.10, 3000, 4500, 0, 0, 1);
        note(s, 1.50, 0.10, 3000, 4500, 0, 0, 1);
        note(s, 1.65, 0.22, 4400, 3100, 28, 300, 1);
        return s;
    }

    private static short[] cuckoo() {
        short[] s = buffer(1.9);
        for (int rep = 0; rep < 1; rep++) {
            // "cu-ckoo": a falling minor third, with an octave added so small speakers carry it
            note(s, 0.00, 0.26, 1320, 1300, 0, 0, 0.6);
            note(s, 0.00, 0.26, 2640, 2600, 0, 0, 0.4);
            note(s, 0.38, 0.42, 1050, 1030, 0, 0, 0.6);
            note(s, 0.38, 0.42, 2100, 2060, 0, 0, 0.4);
        }
        return s;
    }

    private static short[] siren() {
        short[] s = buffer(2.0);
        double phase = 0;
        for (int i = 0; i < s.length; i++) {
            double t = (double) i / s.length;
            double f = 1500 + 900 * Math.sin(2 * Math.PI * t - Math.PI / 2);
            phase += 2 * Math.PI * f / RATE;
            double v = Math.sin(phase) + 0.35 * Math.sin(3 * phase);
            s[i] = (short) (Math.max(-1, Math.min(1, v * 0.8)) * 30000);
        }
        return s;
    }

    private static short[] beeps() {
        short[] s = buffer(1.3);
        for (int i = 0; i < 3; i++) {
            note(s, i * 0.26, 0.17, 2900, 2900, 0, 0, 0.7);
            note(s, i * 0.26, 0.17, 3650, 3650, 0, 0, 0.3);
        }
        return s;
    }
}
